const { createCrossmint } = require("@crossmint/wallets-sdk");

async function main() {
  const log = {
    sender_chain: "base-sepolia",
    receiver_chain: "base-sepolia",
    amount: "0.001",
    token: "USDC",
    sender_address: "mock-sender",
    receiver_address: "mock-receiver",
    transfer_status: "mock"
  };

  try {
    // Initialize the Crossmint client
    const crossmint = createCrossmint({
      apiKey: process.env.CROSSMINT_API_KEY,
    });

    console.log("Crossmint client initialized");

    // Create or get sender wallet
    const senderWallet = await crossmint.wallets.createWallet({
      type: "evm-smart-wallet",
      chain: "base-sepolia",
      locator: "userId:sender-001",
      config: {
        recovery: {
          method: "server",
          secret: process.env.SIGNER_SECRET,
        },
      },
    });

    log.sender_address = senderWallet.address || "mock-sender";
    console.log("Sender wallet:", senderWallet.address);

    // Create or get receiver wallet
    const receiverWallet = await crossmint.wallets.createWallet({
      type: "evm-smart-wallet",
      chain: "base-sepolia",
      locator: "userId:receiver-001",
      config: {
        recovery: {
          method: "server",
          secret: process.env.SIGNER_SECRET,
        },
      },
    });

    log.receiver_address = receiverWallet.address || "mock-receiver";
    console.log("Receiver wallet:", receiverWallet.address);

    // USDC contract address on Base Sepolia
    const usdcContractAddress = "0x036CbD53842c5426634e7929541eC2318f3dCF7e";
    const amount = "0.001";

    // Transfer USDC from sender to receiver
    console.log(`Transferring ${amount} USDC from ${senderWallet.address} to ${receiverWallet.address}`);

    const transferResult = await crossmint.wallets.transfer({
      wallet: senderWallet.wallet,
      to: receiverWallet.address,
      amount: amount,
      token: usdcContractAddress,
      chain: "base-sepolia",
    });

    console.log("Transfer result:", transferResult);
    log.transfer_status = "submitted";

  } catch (error) {
    console.error("Error during transfer:", error.message);
    log.transfer_status = "failed";
    log.error = error.message;
  }

  // Write the log to JSON file
  const fs = require("fs");
  const path = "/home/user/transfer_log.json";
  fs.writeFileSync(path, JSON.stringify(log, null, 2));
  console.log(`Log written to ${path}`);
}

main().catch(console.error);

